(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["yo"] = {"ui":{"skip":"Fo lọ sí àkóónú","back":"← Padà sí AI-gile","lang.button":"Èdè: {name}","lang.dialog":"Yan èdè kan","lang.search":"Wá èdè","lang.none":"Kò sí èdè tó bá a mu","lang.notYet":"A kò tíì túmọ̀ {name}","theme.aria":"Yí padà láàrin àkòrí ìmọ́lẹ̀ àti òkùnkùn","theme.toLight":"Yí padà sí àkòrí ìmọ́lẹ̀","theme.toDark":"Yí padà sí àkòrí òkùnkùn","index.title":"AI-gile: ẹgbẹ́ AI rẹ tó ń kọ́ sọfitiwia, lórí pátákó kan","index.description":"AI-gile jẹ́ pátákó kanban fún àwọn ẹgbẹ́ AI tó ń kọ kóòdù. Wọ́n ń ṣiṣẹ́ nígbà tí o bá sùn; ìwọ yóò rí ìdìpọ̀ kékeré kan ti àwọn nǹkan láti pinnu lé, láti ṣe àyẹ̀wò àti láti gbà.","hero.logoAlt":"Àmì pátákó AI-gile","hero.h1.html":"Ẹgbẹ́ AI rẹ tó ń kọ́ sọfitiwia, lórí pátákó&nbsp;kan.","hero.alpha":"🐣 Pre-alpha tí a pa mọ́","hero.alphaTitle":"Ó ṣì wà ní ìbẹ̀rẹ̀, kò sì tíì parí: a dúpẹ́ pé o ń gbìyànjú rẹ̀!","hero.lede":"Wọ́n ń kọ́ nígbà tí o bá sùn. O jí sí ìdìpọ̀ kékeré kan: ìbéèrè díẹ̀, àwọn nǹkan díẹ̀ láti ṣe àyẹ̀wò, dáyámọ́ǹdì elése àlùkò kan tàbí méjì. Tẹ̀, gbà, kí o sì padà sí kọfí rẹ.","dl.windows":"Ohun èlò Windows","dl.browser":"Lò ó nínú ẹ̀rọ aṣàwákiri rẹ","dl.soon":"Ń bọ̀ láìpẹ́","dl.notify":"🔔 Sọ fún mi nígbà tó bá ṣí","dl.notifySmall":"Alpha tàbí beta","hero.secondary":"Agile ni, ṣùgbọ́n ẹgbẹ́ náà kì í nílò kọfí stand-up. (Wọ́n ń ṣe stand-up lọ́nàkọnà.)","pitch.h2":"AI-gile ní iye ọ̀rọ̀ tí o fẹ́","pitch.lede":"Yan gígùn kan, láti ọ̀rọ̀ kan títí dé 144. Gígùn kọ̀ọ̀kan jẹ́ àpèjúwe tirẹ̀, tí a kọ fún ìwọ̀n yẹn. Fa ìgbámú náà tàbí lo àwọn kọ́kọ́rọ́ ọfà.","pitch.rangeLabel":"Gígùn ní iye ọ̀rọ̀","pitch.dice":"🎲 ẹ̀dà mìíràn","pitch.words.one":"ọ̀rọ̀ {n}","pitch.words.other":"ọ̀rọ̀ {n}","pitch.letters.one":"lẹ́tà {n}","pitch.letters.other":"lẹ́tà {n}","pitch.chars.one":"àmì {n}","pitch.chars.other":"àmì {n}","count.line.html.one":"káàdì {n} wà lórí pátákó báyìí","count.line.html.other":"káàdì {n} wà lórí pátákó báyìí","features.aria":"Ohun tó ń ṣe","f.pile.h":"Ìdìpọ̀ kan fún ọ","f.pile.html":"<b>Fún ọ</b> kó gbogbo ohun tó ń dúró de ọ jọ káàkiri gbogbo iṣẹ́ àkànṣe: ìbéèrè, àwọn nǹkan láti ṣe àyẹ̀wò, àwọn iṣẹ́ tí ènìyàn nìkan lè ṣe. Ìlà rẹ sọ ohun tó kàn àti bí yóò ti pẹ́ tó.","f.sleep.h":"Àwọn ẹgbẹ́ tó ń ṣiṣẹ́ nígbà tí o bá sùn","f.sleep.p":"Iṣẹ́ àkànṣe kọ̀ọ̀kan ní olórí àti ẹgbẹ́ àwọn aṣojú AI. Sọ ọ̀rọ̀ lórí káàdì kan, ẹgbẹ́ náà yóò jí, yóò ṣe iṣẹ́ náà, yóò sì dá a padà pẹ̀lú àwọn ìgbésẹ̀ tí ènìyàn tó rẹ̀ lè tẹ̀lé.","f.tester.h":"Olùdánwò AI máa ń ṣe àyẹ̀wò ní àkọ́kọ́","f.tester.p":"Kí ohunkóhun tó dé ọ̀dọ̀ rẹ, olùdánwò á tẹ̀lé àwọn ìgbésẹ̀ nínú àdàkọ ohun èlò náà, á sì fi ohun tó rí hàn, pẹ̀lú àwòrán ojú ìwé. Yára wo àwọn tó yege, kí o sì gbà wọ́n pẹ̀lú títẹ̀ kan.","f.proof.h":"Ẹ̀rí, kì í ṣe ìlérí","f.proof.p":"Ìfìlọ́lẹ̀ kọ̀ọ̀kan fi ohun tó yípadà hàn: àwọn fáìlì, ìyàtọ̀, àwọn àwòrán ojú ìwé. Kò sí ṣíṣí gbogbo ohun èlò láti rí i bóyá ó ti parí.","f.chat.h":"Bá àwọn olórí rẹ sọ̀rọ̀","f.chat.p":"Ọ̀pá ẹ̀gbẹ́ bí ti Discord: àmì kan fún iṣẹ́ àkànṣe kọ̀ọ̀kan, dáyámọ́ǹdì elése àlùkò fún ohun tó nílò rẹ. Fi èrò ránṣẹ́ sí olórí kan; wọn á yí i sí àwọn káàdì àti ètò, pẹ̀lú bọ́tìnì ✅ Bẹ̀rẹ̀.","f.tidy.h":"Ó ń tún ara rẹ̀ ṣe","f.tidy.p":"Àwọn káàdì tó jọra ń dá pọ̀ di ọ̀kan, àwọn àkọlé tó dàrú ń di títúnṣe, àyẹ̀wò tóòkénì sì ń jẹ́ kí kóòdù kéré. Àwọn nǹkan díẹ̀ láti máa yípadà láàrin wọn, kéré láti rò.","f.private.h":"Tìrẹ ni, lórí kọ̀ǹpútà rẹ","f.private.li1":"Pátákó náà ń ṣiṣẹ́ lórí ẹ̀rọ rẹ, ó sì ń dáhùn sí ìwọ nìkan.","f.private.li2":"Àwọn ìfiránṣẹ́ àdáni láàrin àwọn ènìyàn jẹ́ fífi ìdìbò pamọ́ láti ìbẹ̀rẹ̀ dé ìparí.","f.private.li3":"Kò sí àkáǹtì, kò sí olùtọpa, kò sí kúkì.","f.lang.h":"Ní èdè rẹ","f.lang.p":"Ju èdè 120 lọ, láti Dutch, Welsh àti Japanese dé pirate, Yoda àti Klingon, pẹ̀lú ìyípadà kíákíá padà sí Gẹ̀ẹ́sì fún àwọn ọ̀rọ̀ olùgbéjáde.","tl.aria":"Àkókò láti ìjíròrò àkọ́kọ́ títí dé ọ̀nà ìrìnàjò ọjọ́ iwájú","tl.h2":"Láti ìjíròrò àkọ́kọ́ dé ohun tó kàn","tl.lede":"Àwọn déètì àti àkókò gidi, ní agbègbè àkókò tìrẹ. Lẹ́yìn òní, ètò ni, kò sì sí déètì tí a ṣèlérí.","tl.today":"Òní","tl.planned":"a ti gbèrò","tl.cards.one":"káàdì {n}","tl.cards.other":"káàdì {n}","join.h2":"Darapọ̀ mọ́ wa","join.lede":"Ènìyàn kékeré kan àti ọ̀pọ̀lọpọ̀ aṣojú onísùúrù ni wọ́n ń kọ́ AI-gile. Ó jẹ́ ti àdáni báyìí, nínú alpha tí a pa mọ́ pẹ̀lú àwọn ọ̀rẹ́. Ṣé o fẹ́ gbìyànjú nígbà tó bá ṣí?","join.btn":"Forúkọ sílẹ̀ fún ìfẹ́","join.small":"A ó fi ímeèlì ránṣẹ́ sí ọ, kò sí ohun mìíràn","footer.tag":"AI-gile. Kò sí olùtọpa, kò sí kúkì, kò sí kọfí stand-up.","footer.licence":"Ìwé àṣẹ iṣẹ́","footer.status":"Ipò","form.sending":"Ń fi ránṣẹ́…","form.failed":"Kò ṣiṣẹ́: gbìyànjú lẹ́ẹ̀kan sí i lẹ́yìn náà.","form.offline":"A kò lè dé AI-gile: gbìyànjú lẹ́ẹ̀kan sí i lẹ́yìn náà.","interest.title":"AI-gile: sọ fún mi nígbà tí alpha bá ṣí","interest.description":"Fi ímeèlì rẹ sílẹ̀ láti gbọ́ nígbà tí alpha tàbí beta tí a pa mọ́ ti AI-gile bá ṣí.","interest.h1":"🔔 Sọ fún mi nígbà tó bá ṣí","interest.lede":"AI-gile wà nínú pre-alpha tí a pa mọ́. Fi ímeèlì rẹ sílẹ̀, a ó sì kọ̀wé lẹ́ẹ̀kan, nígbà tí ààyè bá wà fún ọ.","interest.email":"Ímeèlì rẹ","interest.which":"Ìdánwò wo?","interest.alpha":"Alpha tí a pa mọ́: ní ìbẹ̀rẹ̀, kò dán, ọ̀pọ̀ ìyípadà","interest.beta":"Beta: ó dúró ṣinṣin jù, lẹ́yìn náà","interest.both":"Èyíkéyìí, èyí tó bá kọ́kọ́ dé","interest.submit":"Fi mí sórí àtòjọ náà","interest.thanks":"O ṣeun! O wà lórí àtòjọ náà.","licence.title":"AI-gile: ìwé àṣẹ iṣẹ́","licence.description":"Ṣé ò ń lo AI-gile nínú iṣẹ́ rẹ? Béèrè fún ìwé àṣẹ iṣẹ́ ọ̀fẹ́.","licence.h1":"📜 Ìwé àṣẹ iṣẹ́","licence.lede":"Ṣé ò ń lo AI-gile níbi iṣẹ́? Sọ ẹni tí o jẹ́ àti ohun tí ò ń ṣe fún wa. Tí ó bá ṣe rere kan, ìwé àṣẹ náà jẹ́ ọ̀fẹ́.","licence.company":"Ilé iṣẹ́","licence.website":"Ojú òpó wẹ́ẹ̀bù","licence.what":"Ohun tí ò ń ṣe","licence.how":"Bí ó ṣe ń ran ayé lọ́wọ́","licence.email":"Ímeèlì","licence.submit":"Béèrè","licence.thanks":"O ṣeun! A ó dáhùn nípasẹ̀ ímeèlì.","status.title":"Ipò AI-gile","status.h1":"Ipò AI-gile","status.quiet":"Gbogbo nǹkan parọ́rọ́","status.checking":"Ń ṣe àyẹ̀wò…","status.offline":"A kò lè dé iṣẹ́ ipò báyìí (ń gbìyànjú lẹ́ẹ̀kan sí i)","status.updated":"a ṣe ìmúdójúìwọ̀n {ago}","status.justNow":"ní ìsinsin yìí","status.min":"ìṣẹ́jú {n} sẹ́yìn","status.hours":"wákàtí {n} sẹ́yìn","status.days":"ọjọ́ {n} sẹ́yìn","live.h2":"Wo bí a ṣe ń kọ́ ọ, láàyè","live.caption":"A ti fi gbogbo káàdì pamọ́: o ń rí ìrísí iṣẹ́ náà, kì í ṣe àwọn ọ̀rọ̀.","live.watching.one":"láàyè: {n} ń wò","live.watching.other":"láàyè: {n} ń wò","live.offline":"Pátákó láàyè ń sinmi díẹ̀. Padà wá láìpẹ́.","live.cols":"Backlog|Láti ṣe|Ń lọ lọ́wọ́|Ẹgbẹ́ ń ṣàyẹ̀wò|Fún ọ láti dánwò|Fún ẹgbẹ́|Ti parí","live.last.now":"A ṣẹ̀ṣẹ̀ gbé káàdì ìkẹyìn","live.last.min.one":"A gbé káàdì ìkẹyìn ní ìṣẹ́jú {n} sẹ́yìn","live.last.min.other":"A gbé káàdì ìkẹyìn ní ìṣẹ́jú {n} sẹ́yìn","live.last.hour.one":"A gbé káàdì ìkẹyìn ní wákàtí {n} sẹ́yìn","live.last.hour.other":"A gbé káàdì ìkẹyìn ní wákàtí {n} sẹ́yìn","live.last.day.one":"A gbé káàdì ìkẹyìn ní ọjọ́ {n} sẹ́yìn","live.last.day.other":"A gbé káàdì ìkẹyìn ní ọjọ́ {n} sẹ́yìn"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Rọ́bọ́ọ̀tì.","Fúnni."]},{"n":2,"texts":["Kanban rọ́bọ́ọ̀tì.","Aṣojú, létòlétò.","Èrò, kíkọ́."]},{"n":3,"texts":["Kanban fún rọ́bọ́ọ̀tì.","Èrò di àwọn ẹ̀yà.","Kanban aṣojú ọ̀fẹ́."]},{"n":5,"texts":["Pátákó kanban tí aṣojú ń darí.","Ìwọ kọ káàdì. Aṣojú kọ́.","Ọ̀fẹ́, nílé, dídánwò, àṣejù díẹ̀."]},{"n":8,"texts":["Pátákó kanban ọ̀fẹ́ tí aṣojú AI ti ń ṣiṣẹ́.","Kọ èrò kan. Aṣojú kọ́ ọ. Ìwọ gbà á.","Agile fún ènìyàn kan àti ọ̀pọ̀ rọ́bọ́ọ̀tì onísùúrù."]},{"n":13,"texts":["Pátákó kanban lórí kọ̀ǹpútà rẹ tí àwọn aṣojú AI ti ń mú àwọn káàdì.","Kọ èrò kan. Ẹgbẹ́ aṣojú kọ́ ọ. Olùdánwò kan ṣe àyẹ̀wò rẹ̀.","Ọ̀fẹ́, kò sí àkáǹtì, kò sí olùtọpa: pátákó kan, àwọn rọ́bọ́ọ̀tì díẹ̀, ìwọ sì ni olórí."]},{"n":21,"texts":["AI-gile jẹ́ pátákó kanban fún bíbá aṣojú AI ṣiṣẹ́. Wọ́n ń mú káàdì; ìwọ ń dán wọn wò, o sì ń gbà wọ́n.","Iṣẹ́ àkànṣe kọ̀ọ̀kan ní olórí àti ẹgbẹ́ àwọn aṣojú AI. Sọ ọ̀rọ̀ lórí káàdì èyíkéyìí, ẹgbẹ́ náà á sì bẹ̀rẹ̀ iṣẹ́.","Pátákó iṣẹ́ àdáni ọ̀fẹ́ kan tó ń ṣiṣẹ́ lórí kọ̀ǹpútà rẹ gan-an. Rọ́bọ́ọ̀tì ni àwọn òṣìṣẹ́. Ẹni tó ń sọ pé bẹ́ẹ̀ ni ni ìwọ."]},{"n":34,"texts":["Ìwọ gbé àwọn èrò sórí pátákó. Ẹgbẹ́ aṣojú AI sọ wọ́n di ẹ̀yà tó ń ṣiṣẹ́, dán wọn wò, kí ó sì dá wọn padà pẹ̀lú ìgbésẹ̀ ìdánwò. Kò sí ohun tó parí títí o fi sọ bẹ́ẹ̀.","AI-gile jẹ́ pátákó kanban tí Rich kọ́ nílé, pẹ̀lú ìrànlọ́wọ́ púpọ̀ láti ọ̀dọ̀ àwọn aṣojú tó ń darí rẹ̀ báyìí. Ọ̀fẹ́ ni, a pín in fún àwọn ọ̀rẹ́, a kì í tà á.","Fojú inú wo pátákó kanban lásán, ọ̀wọ́n láti Backlog dé Done, àfi pé aṣojú AI ló ń mú káàdì. Wọ́n ń ròyìn ìlọsíwájú, wọ́n ń béèrè nígbà tí wọ́n bá di, wọ́n sì ń dúró de ìfohùnṣọ̀kan rẹ."]},{"n":55,"texts":["AI-gile jẹ́ pátákó kanban tí ẹgbẹ́ rẹ̀ jẹ́ àwọn aṣojú AI. Iṣẹ́ àkànṣe kọ̀ọ̀kan ní olórí tó ń gbèrò iṣẹ́ àti àwọn olùrànlọ́wọ́ tó ń kọ́ ọ. Nígbà tí ẹ̀yà kan bá ti ṣetán, olùdánwò AI á dán an wò, á sì yá àwòrán ojú ìwé, lẹ́yìn náà á balẹ̀ sínú ìdìpọ̀ rẹ. Gbà á, tàbí sọ ọ̀rọ̀ kí wọ́n tún un ṣe.","Ó bẹ̀rẹ̀ gẹ́gẹ́ bí ọ̀nà ènìyàn kan láti máa tọpa ọ̀pọ̀ ìgbà kíkọ kóòdù pẹ̀lú AI lẹ́ẹ̀kan náà, ó sì dàgbà di pátákó tó péye. Ó ń ṣiṣẹ́ lórí ẹ̀rọ rẹ, kò nílò àkáǹtì, kò sì ní olùtọpa. Ọ̀fẹ́ ni fún àwọn ọ̀rẹ́ àti ẹnikẹ́ni tó ní ìfẹ́ sí i. Kò tíì parí pẹ̀lú, nítorí náà retí àwọn ibi tí kò dán àti ìyàlẹ́nu díẹ̀.","Èyí ni ẹ̀dà òtítọ́. Ìwọ ṣì gbọ́dọ̀ ní èrò, ìwọ sì ṣì gbọ́dọ̀ yẹ àbájáde wò. AI-gile ń ṣe gbogbo ohun láàrin: ó tò àwọn káàdì, ó jí aṣojú tó tọ́ nígbà tí o bá sọ̀rọ̀, ó fi ohun tó yípadà hàn, ó sì kó gbogbo rẹ̀ sínú ìdìpọ̀ kékeré kan fún ọ."]},{"n":89,"texts":["AI-gile jẹ́ pátákó kanban ọ̀fẹ́ tí ò ń lò lórí kọ̀ǹpútà rẹ gan-an. Dípò ènìyàn, iṣẹ́ àkànṣe kọ̀ọ̀kan ní ẹgbẹ́ àwọn aṣojú AI: olórí kan tó ń sọ àwọn èrò rẹ di káàdì àti ètò, àti àwọn olùrànlọ́wọ́ tó ń mú àwọn káàdì ní ìtòtẹ̀léra pàtàkì. Nígbà tí nǹkan bá ti kọ́, olùdánwò AI á tẹ̀lé àwọn ìgbésẹ̀ ìdánwò, á sì fi ohun tó rí hàn ọ́. Lẹ́yìn náà ó dúró nínú ìdìpọ̀ kan tí a fi àmì Fún ọ sí. Ìwọ gbà á, tàbí kí o sọ ọ̀rọ̀, ẹgbẹ́ náà á sì tún gbìyànjú. Kò sí ohun tó máa dé Done láìsí ìwọ.","Àwọn ẹ̀yà kan wà tí o lè má retí. Ìṣọ́ òru ń jẹ́ kí ọ̀wọ́n Láti ṣe kún nígbà tí o bá sùn, ó ń yan káàdì tí kò nílò ìdáhùn rẹ. Olùkà tóòkénì fi bí aṣojú ṣe lò tó hàn, ipò No Token Mode sì ń sọ fún wọn kí wọ́n dáwọ́ dúró. O lè fi ìfiránṣẹ́ àdáni ránṣẹ́ sí àwọn ọ̀rẹ́, wọ́n sì jẹ́ fífi ìdìbò pamọ́. Pátákó náà ń sọ nǹkan bí èdè 120, pẹ̀lú pirate àti Klingon. Kò sí èyí tó ń ná owó, kò sì sí ẹni tó ń tà á fún ọ.","AI-gile jẹ́ iṣẹ́ àkànṣe kékeré, ti ara ẹni, kì í ṣe ilé iṣẹ́. Rich fẹ́ máa tọ́jú ọ̀pọ̀ iṣẹ́ àkànṣe kóòdù AI láìṣí ohun èlò kọ̀ọ̀kan láti wò wọ́n, nítorí náà òun àti àwọn aṣojú kọ́ pátákó kan, wọ́n sì lò ó láti kọ́ ìyókù ara rẹ̀. Ó wà nínú pre-alpha tí a pa mọ́: ó ń ṣiṣẹ́, ní pàtàkì, fún àwọn ọ̀rẹ́ díẹ̀. Kò sí ojú ìwé iye owó, ìwé ìròyìn tàbí ètò ìdàgbàsókè. Tí ó bá dún bí ohun tó wúlò, béèrè láti gbìyànjú rẹ̀ nígbà tó bá ṣí sí i."]},{"n":144,"texts":["AI-gile jẹ́ pátákó kanban fún ènìyàn kan àti ọ̀pọ̀lọpọ̀ aṣojú AI. Ó ń ṣiṣẹ́ lórí kọ̀ǹpútà rẹ gan-an, ó sì jẹ́ ọ̀fẹ́ pátápátá. Ìwọ ń fi àwọn iṣẹ́ àkànṣe kún un, iṣẹ́ àkànṣe kọ̀ọ̀kan sì ń ní olórí àti ẹgbẹ́ kékeré kan. Ìwọ ń bá olórí sọ̀rọ̀, díẹ̀ bí Discord, o sì ṣàpèjúwe èrò kan; olórí yóò sọ ọ́ di káàdì àti ètò, lẹ́yìn náà yóò dúró kí o tẹ Bẹ̀rẹ̀. Ẹgbẹ́ náà ń lọ láàrin àwọn káàdì ní ìtòtẹ̀léra pàtàkì, wọ́n ń lo ìlà àṣẹ tó rọrùn tí a ṣe fún àwọn àwòṣe èdè. Kí ohunkóhun tó padà dé ọ̀dọ̀ rẹ, olùdánwò AI á tẹ̀lé àwọn ìgbésẹ̀ nínú àdàkọ ohun èlò náà, á sì so àwòrán ojú ìwé mọ́ ọn. Iṣẹ́ tí a parí ń balẹ̀ sínú ìdìpọ̀ rẹ pẹ̀lú àwọn fáìlì tó yípadà àti ìyàtọ̀. Ìwọ gbà á, tàbí kí o fi ọ̀rọ̀ sílẹ̀, ẹgbẹ́ náà á sì jí, á gbìyànjú lẹ́ẹ̀kan sí i. Ìwọ nìkan ló lè gbé káàdì lọ sí Done.","Ọjọ́ kan pẹ̀lú AI-gile, ní àlàyé kúkúrú. Ní ìrọ̀lẹ́, o fi àwọn ọ̀rọ̀ díẹ̀ sílẹ̀: bọ́tìnì yìí wà ní ibi tí kò tọ́, àtòjọ yẹn yẹ kí a tò ó, ṣé a lè ní ipò òkùnkùn. O lọ sùn. Àwọn aṣojú ka àwọn ọ̀rọ̀ náà, wọ́n ṣe àwọn àtúnṣe, wọ́n dán wọn wò, wọ́n sì dá wọn padà fún ọ. Tí Láti ṣe bá gbẹ, ìṣọ́ òru yóò fi àwọn káàdì tí kò nílò ìdáhùn láti ọ̀dọ̀ rẹ kún un láti inú backlog. Ní òwúrọ̀, ìdìpọ̀ kékeré kan wà: ìbéèrè díẹ̀ àti àwọn nǹkan díẹ̀ láti gbìyànjú, ọ̀kọ̀ọ̀kan pẹ̀lú àwọn ìgbésẹ̀ tí ẹni tó ń sùn lè tẹ̀lé àti àwòrán ojú ìwé tó fi hàn pé ó ń ṣiṣẹ́. O tẹ̀ wọ́n kọjá, o gba àwọn tó dára, o sì dá ìyókù padà. Olùkà tóòkénì fi bí gbogbo rẹ̀ ṣe lò tó hàn, ipò No Token Mode sì wà fún àwọn ọ̀sẹ̀ tí a fẹ́ fi pamọ́. Lẹ́yìn náà o jẹ oúnjẹ àárọ̀, èyí tí àwọn aṣojú kò tíì lè ràn lọ́wọ́.","Àkọ́kọ́, ohun tí AI-gile kì í ṣe. Kì í ṣe ilé iṣẹ́ tuntun, a kì í tà á, kò sì sí ẹni tó ń kó dátà rẹ jọ. Pátákó ọ̀fẹ́ ni tó ń ṣiṣẹ́ lórí kọ̀ǹpútà rẹ, láìsí àkáǹtì, olùtọpa àti kúkì. Ohun tó jẹ́: ibi mímọ́ kan láti rí gbogbo iṣẹ́ àkànṣe kóòdù AI, pẹ̀lú ẹgbẹ́ aṣojú tó ń ṣe àwọn káàdì àti ìwọ tó ń ṣe ìpinnu. Ó ń dá káàdì tó jọra pọ̀, ó ń tún àkọlé tó dàrú ṣe, ó sì ń ṣọ́ kí kóòdù kéré. Ó ń sọ nǹkan bí èdè 120, láti Dutch àti Flemish dé pirate àti Klingon. Àwọn ọ̀rẹ́ lè fi ìfiránṣẹ́ ránṣẹ́ sí ara wọn, ní àdáni àti ní fífi ìdìbò pamọ́. Rich àti ọ̀pọ̀lọpọ̀ aṣojú onísùúrù ló kọ́ ọ, pàápàá nípa lílo ara rẹ̀. Ó wà nínú pre-alpha tí a pa mọ́, nítorí náà kò dán ní àwọn ibì kan. Tí ó bá dún bí eré, béèrè dáadáa, o sì lè wọlé ní kùtùkùtù."]}],"quips":{"1":"Ọ̀rọ̀ kan. Gbóyà. Bóyá ó gbóyà jù.","3":"Ọ̀rọ̀ mẹ́ta. Ó ti jẹ́ òtítọ́ ju ọ̀pọ̀ ojú ìwé ọjà lọ.","8":"Ọ̀rọ̀ mẹ́jọ. Ó ṣì kúrú ju stand-up lọ.","21":"Ojú ìwọ̀n ìtàn ni àwọn gígùn wọ̀nyí, bí o bá fẹ́ mọ̀. Dájúdájú.","55":"Ọ̀rọ̀ márùndínlọ́gọ́ta. Káàdì méjì ti parí nígbà tí ò ń ka èyí.","144":"Èyí ni èyí tó gùn. Kò sí 233. Àwọn aṣojú ti lọ sùn."}},"timeline":{"first-idea.name":"Èrò àkọ́kọ́","first-idea.line":"Ìjíròrò àkọ́kọ́ gan-an, kí kóòdù kankan tó wà.","first-board.name":"Pátákó àkọ́kọ́","first-board.line":"Pátákó tó ń tọpa bí a ṣe kọ́ ọ: káàdì, ọ̀wọ́n, fà-àti-ju, iṣẹ́ àkànṣe.","team-roles.name":"Ẹgbẹ́ àti ipa","team-roles.line":"Àwọn àkọsílẹ̀ aṣojú, àwòṣe ẹgbẹ́, ààyè àti ẹni tó ń ṣe kí ni.","install.name":"Fífi sórí ẹ̀rọ àti àwọn ìtẹ̀jáde","install.line":"Zip tí ọ̀rẹ́ lè fi sórí ẹ̀rọ, ìmúdójúìwọ̀n ara ẹni, àwọn ọ̀nà àti ìpadàsẹ́yìn.","usage-saver.name":"Olùfi lílò pamọ́","usage-saver.line":"Wọn ohun tí ìṣiṣẹ́ ń náni, jẹ́ kí kóòdù kéré, fi ààlà rẹ pamọ́.","friends.name":"Àwọn ọ̀rẹ́ àti pípín","friends.line":"Àwọn ìfiránṣẹ́ àdáni, ìgbéránṣẹ́ tí a dàrú, ìkésí, ipa àti àwọn iṣẹ́ àkànṣe tí a pín.","languages.name":"Àwọn èdè","languages.line":"Gbogbo ọ̀rọ̀ ojú ìwé nínú fáìlì èdè, pẹ̀lú Dutch àti Flemish ní àkọ́kọ́.","ai-tester.name":"Olùdánwò AI","ai-tester.line":"Olùdánwò máa ń ṣe àyẹ̀wò gbogbo ìfìlọ́lẹ̀ ní àkọ́kọ́, ó sì fi ohun tó rí hàn.","website.name":"Ojú òpó wẹ́ẹ̀bù","website.line":"aigile.lol, ìfihàn kékeré àti àkókò yìí.","streaming.name":"Ìjíròrò àti ìgbóhùnsáfẹ́fẹ́","streaming.line":"Discord, Twitch, OBS, ipò olùgbóhùnsáfẹ́fẹ́, GIF àti àwọn emoji.","no-ai.name":"Àtẹ̀jáde láìsí AI","no-ai.line":"Pátákó fún àwọn tó ń kọ kóòdù láìsí AI, àti àwọn pátákó gbangba.","night-watch.name":"Ìṣọ́ òru","night-watch.line":"Aṣọ́ àti Scrum Master ń jẹ́ kí àwọn ẹgbẹ́ dúró lórí iṣẹ́ nígbà tí o bá sùn.","p-more.name":"Gbogbo ohun yòókù","p-more.line":"Àwọn èrò kékeré tó ṣì ń dúró de àkókò wọn.","p-android.name":"Fóònù àti Android","p-android.line":"Dé pátákó rẹ láti fóònù, lẹ́yìn náà ohun èlò Android abínibí.","p-release.name":"Alpha àti ohun tó ré kọjá","p-release.line":"Alpha tí a pa mọ́, ojú òpó tó wà láàyè, lẹ́yìn náà beta.","p-languages.name":"Àwọn èdè púpọ̀ sí i","p-languages.line":"Ju ọgọ́rùn-ún èdè lọ, àti ipò ríbọmi fún àwọn akẹ́kọ̀ọ́.","p-engines.name":"Àwọn ẹ̀rọ AI púpọ̀ sí i","p-engines.line":"Yan Claude, Codex tàbí Gemini fún aṣojú kọ̀ọ̀kan.","p-pro.name":"Ìṣe ọ̀jọ̀gbọ́n","p-pro.line":"Àwọn àmì ewu, ẹnu-ọ̀nà ìdàpọ̀, káàdì ìṣẹ̀lẹ̀ àti àwọn ìdènà ààbò.","p-self.name":"Ríṣọ́ ọ","p-self.line":"Ipò àárẹ̀, àwọn ìránnilétí ìtọ́jú ara ẹni àti 4:20.","p-servers.name":"Àwọn sáfà àti ìdàgbàsókè","p-servers.line":"Àwọn ètò sáfà gbogbogbò, ipa àti ṣíṣètò fún ìdàgbàsókè.","p-livestream.name":"Àwọn àfikún ìgbóhùnsáfẹ́fẹ́","p-livestream.line":"Ìjíròrò Twitch, àwọn emoji àdáni àti ìwòran gbangba tó wà láàyè."},"words":{"button":"📖 Àwọn ọ̀rọ̀ olùgbéjáde","h":"📖 Àlàyé àwọn ọ̀rọ̀ olùgbéjáde","intro":"Àwọn ọ̀rọ̀ tí àwọn olùgbéjáde (àti àwọn ẹgbẹ́ AI) ń lò, ní èdè tó rọrùn.","search":"Wá ọ̀rọ̀ kan…","none":"Kò sí ọ̀rọ̀ tó bá a mu.","close":"Ti","list":[{"id":"backlog","word":"Backlog","text":"Àwọn èrò àti iṣẹ́ tí a kò tíì ṣètò. Kò sí ohun tí a ó ṣiṣẹ́ lé níbẹ̀ títí yóò fi lọ sí Láti ṣe."},{"id":"sprint","word":"Sprint","text":"Àkókò kúkúrú iṣẹ́ (ọ̀pọ̀ ìgbà ọ̀sẹ̀ kan tàbí méjì) pẹ̀lú àwọn káàdì tí a gbà láti parí.","also":["sprints"]},{"id":"standup","word":"Stand-up","text":"Ìpàdé kúkúrú: ohun tí ọmọ ẹgbẹ́ kọ̀ọ̀kan ṣe, ohun tí yóò ṣe tókàn, àti ohun tó ń dí i lọ́wọ́.","also":["standup","stand-ups"]},{"id":"bug","word":"Bug","text":"Nǹkan tí kò ṣiṣẹ́ bí ó ti yẹ.","also":["bugs"]},{"id":"test","word":"Idánwò","text":"Dídán iṣẹ́ tí a parí wò láti rí i pé ó ń ṣe ohun tí a béèrè, kí o tó gbà á.","also":["dánwò","idánwò","àwọn idánwò","test","tests"],"noTip":1},{"id":"commit","word":"Commit","text":"Àwòrán kóòdù tí a fi pamọ́, pẹ̀lú àkíyèsí kúkúrú ohun tó yí padà. O lè padà sí ọ̀kan nígbà gbogbo.","also":["commits"]},{"id":"push","word":"Push","text":"Fífi àwọn àwòrán tí a fi pamọ́ (commits) ránṣẹ́ láti kọ̀ǹpútà yìí sí GitHub, kí a lè ní ẹ̀dà àti kí a pín wọn."},{"id":"branch","word":"Branch","text":"Ìlà iṣẹ́ tó yàtọ̀ nínú kóòdù, kí a lè ṣe àyípadà láì fọwọ́ kan ẹ̀dà pàtàkì.","also":["branches"]},{"id":"merge","word":"Merge","text":"Dída àwọn àyípadà branch padà sínú ẹ̀dà pàtàkì."},{"id":"repo","word":"Repo","text":"Fódà kóòdù iṣẹ́ àkànṣe àti gbogbo ìtàn commits rẹ̀, tí a sábà máa ń tọ́jú sórí GitHub pẹ̀lú.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"Títo kóòdù láì yí ohun tó ń ṣe padà: àwọn fáìlì kékeré, orúkọ tó ṣe kedere, àtúnsọ díẹ̀."},{"id":"deploy","word":"Deploy","text":"Fífi ẹ̀dà tuntun sórí ayélujára, fún àpẹẹrẹ sórí sáfà tí àwọn ènìyàn ti ń lò ó."},{"id":"kanban","word":"Kanban","text":"Pátákó pẹ̀lú àwọn ọ̀wọ́n (Láti ṣe, Ń lọ lọ́wọ́, Ti parí) níbi tí àwọn káàdì ti ń lọ láti òsì sí ọ̀tún bí iṣẹ́ ṣe ń lọ."},{"id":"wip","word":"Ààlà WIP","text":"Iṣẹ́ tó ń lọ lọ́wọ́: iye káàdì púpọ̀ jù tí ọ̀wọ́n gbọ́dọ̀ mú, kí ẹgbẹ́ lè parí nǹkan kí ó tó bẹ̀rẹ̀ mìíràn.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Bíbéèrè pé kí a ṣàyẹ̀wò àwọn àyípadà branch kí a sì dà wọ́n sínú ẹ̀dà pàtàkì.","also":["PR"]},{"id":"hook","word":"Hook","text":"Àṣẹ kékeré tó ń ṣiṣẹ́ fúnra rẹ̀ ní àkókò kan, fún àpẹẹrẹ nígbà tí àkókò AI bá bẹ̀rẹ̀, kí ẹgbẹ́ lè gbọ́ àwọn ọ̀rọ̀ rẹ.","also":["hooks"]},{"id":"token","word":"Token","text":"Ẹyọ tí a fi ń ka lílo AI: ó tó àwọn lẹ́tà díẹ̀ ọ̀rọ̀ tí a kà tàbí tí a kọ. Token tó kéré, ètò rẹ tó ṣẹ́ kù á pọ̀ sí i.","also":["tokens"]},{"id":"agent","word":"Aṣojú","text":"AI tó ń ṣiṣẹ́ fúnra rẹ̀ lórí iṣẹ́ kan: ó ń ka kóòdù, ó ń ṣe àyípadà, ó ń ṣiṣẹ́ àyẹ̀wò, ó sì ń ròyìn padà.","also":["aṣojú","àwọn aṣojú","agents","agent"]}]}};
